// so the Rust port can be differentially tested op-by-op.
//
//   oracle <specfile>
//
// Spec file format (whitespace separated tokens, one directive per line):
//   OP        union1 | union2 | intersect | difference | xor | inflate | bounds | translate | area
//   FILL      0..3          (EvenOdd=0 NonZero=1 Positive=2 Negative=3)
//   DELTA     <f64>
//   JOIN      0..3          (Square=0 Bevel=1 Round=2 Miter=3)
//   END       0..4          (Polygon=0 ...)
//   MITER     <f64>         default 2.0
//   ARCTOL    <f64>         default 0.0
//   DX <i64>  DY <i64>
//   SUBJECT                 following PATH lines belong to subject
//   CLIP                    following PATH lines belong to clip
//   PATH      x y x y ...
//
// Output (canonical, identical in format to what the Rust port prints):
//   PATHS <n>
//   <npts> x y x y ...
//   ...
// or  RECT <l> <t> <r> <b>
// or  AREA <bits-as-hex> <decimal>

use std::fmt::Write as _;
use std::process::Command;

const BIN: &str = "/workspace/dataset/test20_executable";
const BASE: u64 = 0x7000_0000;

fn nm_addr(pattern: &str) -> u64 {
    let out = Command::new("nm").arg("-C").arg(BIN).output().expect("nm failed");
    let text = String::from_utf8_lossy(&out.stdout);
    let mut found: Vec<u64> = Vec::new();
    for line in text.lines() {
        if line.contains(pattern) {
            let addr = &line[..16];
            if let Ok(a) = u64::from_str_radix(addr.trim(), 16) {
                found.push(a);
            }
        }
    }
    found.sort();
    found.dedup();
    if found.len() != 1 {
        panic!("pattern {:?} matched {} symbols: {:x?}", pattern, found.len(), found);
    }
    found[0]
}

#[derive(Default)]
struct Spec {
    op: String,
    fill: i32,
    delta: f64,
    join: i32,
    end: i32,
    miter: f64,
    arctol: f64,
    dx: i64,
    dy: i64,
    subject: Vec<Vec<(i64, i64)>>,
    clip: Vec<Vec<(i64, i64)>>,
}

fn parse_spec(text: &str) -> Spec {
    let mut s = Spec { miter: 2.0, ..Default::default() };
    let mut in_clip = false;
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut it = line.split_whitespace();
        let kw = it.next().unwrap();
        match kw {
            "OP" => s.op = it.next().unwrap().to_string(),
            "FILL" => s.fill = it.next().unwrap().parse().unwrap(),
            "DELTA" => s.delta = it.next().unwrap().parse().unwrap(),
            "JOIN" => s.join = it.next().unwrap().parse().unwrap(),
            "END" => s.end = it.next().unwrap().parse().unwrap(),
            "MITER" => s.miter = it.next().unwrap().parse().unwrap(),
            "ARCTOL" => s.arctol = it.next().unwrap().parse().unwrap(),
            "DX" => s.dx = it.next().unwrap().parse().unwrap(),
            "DY" => s.dy = it.next().unwrap().parse().unwrap(),
            "SUBJECT" => in_clip = false,
            "CLIP" => in_clip = true,
            "PATH" => {
                let nums: Vec<i64> = it.map(|t| t.parse().unwrap()).collect();
                let path: Vec<(i64, i64)> = nums.chunks(2).map(|c| (c[0], c[1])).collect();
                if in_clip { s.clip.push(path) } else { s.subject.push(path) }
            }
            _ => panic!("bad directive {kw}"),
        }
    }
    s
}

