//! Reproduction of `std::cout << (double)` under the default stream state.
//!
//! libstdc++'s `num_put<char>` formats a `double` with `%g` and the stream's precision, which
//! defaults to 6. So the whole job is an exact `printf("%g", v)` with precision 6:
//!
//!  * let `x` be the decimal exponent of `v` rounded to 6 significant digits;
//!  * if `-4 <= x < 6` print in fixed notation with `5 - x` fractional digits,
//!    otherwise print in scientific notation with 5 fractional digits;
//!  * then (no `#` flag) strip trailing fractional zeros, and the '.' if nothing follows it.

/// Format `v` exactly as `std::cout << v` would with default flags/precision.
pub fn ostream_double(v: f64) -> String {
    if v.is_nan() {
        return if v.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    }
    if v.is_infinite() {
        return if v < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }

    const PREC: i32 = 6;

    // Rust's `{:.*e}` is correctly rounded, exactly like glibc's `%.*e`, so this hands us the
    // 6 significant decimal digits plus the decimal exponent with no double-rounding.
    let sci = format!("{:.*e}", (PREC - 1) as usize, v);
    let (mant, exp) = sci.split_once('e').expect("{:e} always emits an exponent");
    let exp: i32 = exp.parse().expect("integer exponent");

    let neg = mant.starts_with('-');
    let mant = mant.trim_start_matches('-');
    // 6 significant digits with the point removed.
    let digits: String = mant.chars().filter(|c| *c != '.').collect();
    debug_assert_eq!(digits.len(), PREC as usize);

    let mut out = String::new();
    if neg {
        out.push('-');
    }

    if exp < -4 || exp >= PREC {
        // Scientific notation: d.ddddd e(+/-)dd
        let mut frac = digits[1..].to_string();
        while frac.ends_with('0') {
            frac.pop();
        }
        out.push_str(&digits[..1]);
        if !frac.is_empty() {
            out.push('.');
            out.push_str(&frac);
        }
        out.push('e');
        out.push(if exp < 0 { '-' } else { '+' });
        let a = exp.abs();
        if a < 10 {
            out.push('0');
        }
        out.push_str(&a.to_string());
    } else if exp >= 0 {
        // Fixed notation with the point inside or just after the digit string.
        let ip = (exp + 1) as usize;
        out.push_str(&digits[..ip]);
        let mut frac = digits[ip..].to_string();
        while frac.ends_with('0') {
            frac.pop();
        }
        if !frac.is_empty() {
            out.push('.');
            out.push_str(&frac);
        }
    } else {
        // -4 <= exp <= -1: leading "0." then |exp|-1 zeros then the digits.
        let mut frac = "0".repeat((-exp - 1) as usize);
        frac.push_str(&digits);
        while frac.ends_with('0') {
            frac.pop();
        }
        out.push('0');
        if !frac.is_empty() {
            out.push('.');
            out.push_str(&frac);
        }
    }
    out
}

