    #[inline]
    pub const fn new(x: f64, y: f64) -> Self {
        PointD { x, y }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

impl Rect64 {
    #[inline]
    pub const fn new(left: i64, top: i64, right: i64, bottom: i64) -> Self {
        Rect64 { left, top, right, bottom }
    }
    /// The "invalid" rect Clipper2 starts a bounds accumulation from; it is also what
    /// `GetBounds` returns for an empty input.
    #[inline]
    pub const fn invalid() -> Self {
        Rect64 { left: i64::MAX, top: i64::MAX, right: i64::MIN, bottom: i64::MIN }
    }
    #[inline]
    pub fn width(&self) -> i64 {
        self.right - self.left
    }
    #[inline]
    pub fn height(&self) -> i64 {
        self.bottom - self.top
    }
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.bottom <= self.top || self.right <= self.left
    }
    #[inline]
    pub fn midpoint(&self) -> Point64 {
        Point64::new((self.left + self.right) / 2, (self.top + self.bottom) / 2)
    }
    pub fn contains_pt(&self, pt: Point64) -> bool {
        pt.x > self.left && pt.x < self.right && pt.y > self.top && pt.y < self.bottom
    }
    pub fn contains_rect(&self, rec: &Rect64) -> bool {
        rec.left >= self.left && rec.right <= self.right && rec.top >= self.top && rec.bottom <= self.bottom
    }
    pub fn intersects(&self, rec: &Rect64) -> bool {
        (self.left.max(rec.left) <= self.right.min(rec.right))
            && (self.top.max(rec.top) <= self.bottom.min(rec.bottom))
    }
    pub fn as_path(&self) -> Path64 {
        vec![
            Point64::new(self.left, self.top),
            Point64::new(self.right, self.top),
            Point64::new(self.right, self.bottom),
            Point64::new(self.left, self.bottom),
        ]
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FillRule {
    EvenOdd = 0,
    NonZero = 1,
    Positive = 2,
    Negative = 3,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ClipType {
    NoClip = 0,
    Intersection = 1,
    Union = 2,
