///
/// The loop is unrolled two vertices at a time, which fixes the floating point summation order;
/// the port must keep that order to reproduce the reference bit-for-bit.
pub fn area(path: &[Point64]) -> f64 {
    let cnt = path.len();
    if cnt < 3 {
        return 0.0;
    }
    let mut a = 0.0f64;
    let mut i2 = cnt - 1; // it2 = cend() - 1
    let stop = if cnt & 1 == 0 { cnt - 1 } else { cnt - 1 };
    // `stop` is `cend()-1`, incremented once more when the count is even.
    let stop = if cnt & 1 == 0 { stop + 1 } else { stop };
    let mut i1 = 0usize;
    while i1 != stop {
        a += ((path[i2].y + path[i1].y) as f64) * ((path[i2].x - path[i1].x) as f64);
        i2 = i1 + 1;
        a += ((path[i1].y + path[i2].y) as f64) * ((path[i1].x - path[i2].x) as f64);
        i1 += 2;
    }
    if cnt & 1 != 0 {
        a += ((path[i2].y + path[i1 % cnt].y) as f64) * ((path[i2].x - path[i1 % cnt].x) as f64);
    }
    a * 0.5
}

