pub fn get_bounds(paths: &[Path64]) -> Rect64 {
    let mut r = Rect64::invalid();
    for p in paths {
        for pt in p {
            if pt.x < r.left {
                r.left = pt.x;
            }
            if pt.x > r.right {
                r.right = pt.x;
            }
            if pt.y < r.top {
                r.top = pt.y;
            }
            if pt.y > r.bottom {
                r.bottom = pt.y;
            }
        }
    }
    r
}

/// `Clipper2Lib::GetBounds<int64_t>(const Path64&)`.
pub fn get_bounds_path(path: &[Point64]) -> Rect64 {
    let mut r = Rect64::invalid();
    for pt in path {
        if pt.x < r.left {
            r.left = pt.x;
        }
        if pt.x > r.right {
            r.right = pt.x;
        }
        if pt.y < r.top {
            r.top = pt.y;
        }
        if pt.y > r.bottom {
            r.bottom = pt.y;
        }
    }
    r
}

/// `Clipper2Lib::TranslatePaths<int64_t>(const Paths64&, int64_t, int64_t)`.
pub fn translate_paths(paths: &[Path64], dx: i64, dy: i64) -> Paths64 {
    paths
        .iter()
        .map(|p| p.iter().map(|pt| Point64::new(pt.x + dx, pt.y + dy)).collect())
        .collect()
}

#[inline]
pub fn is_positive(path: &[Point64]) -> bool {
    area(path) >= 0.0
}

