//! The test20 pipeline: geometry construction plus the twenty-step Clipper2 API chain.
//!
//! The pipeline is expressed once here and shared by the shipped binary and the differential
//! test harness; `Observer` lets the harness look at every intermediate `Paths64` without the
//! shipped binary's behaviour changing at all.

use super::core::*;
use super::engine::{difference, intersect, union_self, xor};
use super::offset::inflate_paths;

/// Hook for inspecting pipeline intermediates. The shipped binary uses `NoObserver`.
pub trait Observer {
    fn emit(&mut self, _label: &str, _paths: &[Path64]) {}
    fn emit_rect(&mut self, _label: &str, _r: &Rect64) {}
}

pub struct NoObserver;
impl Observer for NoObserver {}

/// `std::stoi` semantics: skip leading whitespace, accept an optional sign and the leading run
/// of decimal digits, ignore any trailing characters.
pub fn stoi(s: &str) -> Option<i32> {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && (b[i] as char).is_whitespace() {
        i += 1;
    }
    let start = i;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        i += 1;
    }
    let digits_start = i;
    while i < b.len() && b[i].is_ascii_digit() {
        i += 1;
    }
    if i == digits_start {
        return None;
    }
    s[start..i].parse::<i32>().ok()
}

/// Build the three geometry layers exactly as the C++ test does.
pub fn build_geometry(complexity: i32) -> Vec<Paths64> {
    let mut geometry_layers: Vec<Paths64> = Vec::new();

    // Layer 1: circles and squares.
    let mut layer1: Paths64 = Vec::new();
    for i in 0..complexity {
        let mut circle: Path64 = Vec::new();
        for j in 0..24 {
            let angle = 2.0 * 3.1415926 * (j as f64) / 24.0;
            let x = 100 + (i as i64) * 80 + (40.0 * angle.cos()) as i64;
            let y = 100 + (40.0 * angle.sin()) as i64;
            circle.push(Point64::new(x, y));
