        square.push(Point64::new(200 + (i as i64) * 60 + size, 200));
        square.push(Point64::new((200 + i * 60) as i64 + size, 200 + size));
        square.push(Point64::new(200 + (i as i64) * 60, 200 + size));
        layer1.push(square);
    }
    geometry_layers.push(layer1);

    // Layer 2: stars and spirals.
    let mut layer2: Paths64 = Vec::new();
    for i in 0..complexity {
        let mut star: Path64 = Vec::new();
        let points = 5 + i;
        for j in 0..points * 2 {
            let angle = 2.0 * 3.1415926 * (j as f64) / ((points * 2) as f64);
            let radius = if j % 2 == 0 { 35.0 } else { 20.0 };
            let x = 150 + (radius * angle.cos()) as i64;
            let y = 150 + (i as i64) * 100 + (radius * angle.sin()) as i64;
            star.push(Point64::new(x, y));
        }
        layer2.push(star);

        let mut spiral: Path64 = Vec::new();
        for j in 0..30 {
