            let mut hex: Path64 = Vec::new();
            let center_x: i64 = 50 + (i as i64) * 70;
            let center_y: i64 = 300 + (j as i64) * 70;
            for k in 0..6 {
                let angle = 2.0 * 3.1415926 * (k as f64) / 6.0;
                let x = center_x + (25.0 * angle.cos()) as i64;
                let y = center_y + (25.0 * angle.sin()) as i64;
                hex.push(Point64::new(x, y));
            }
            layer3.push(hex);

            let mut triangle: Path64 = Vec::new();
            triangle.push(Point64::new(center_x + 100, center_y));
            triangle.push(Point64::new(center_x + 100 + 30, center_y + 50));
            triangle.push(Point64::new(center_x + 100 - 30, center_y + 50));
            layer3.push(triangle);
        }
    }
    geometry_layers.push(layer3);

    geometry_layers
}

/// Run the twenty-step API chain and return the reported complexity score.
pub fn compute(complexity: i32, obs: &mut dyn Observer) -> f64 {
    let geometry_layers = build_geometry(complexity);
    for (i, l) in geometry_layers.iter().enumerate() {
        obs.emit(&format!("layer{}", i), l);
    }

    // 1-3. Union each layer independently.
    let mut accumulated: Paths64 = Vec::new();
    for layer in &geometry_layers {
        let union_layer = union_self(layer, FillRule::EvenOdd);
        obs.emit("unionLayer", &union_layer);
        accumulated.extend(union_layer);
    }

    // 4. Union of all layers.
    let all_union = union_self(&accumulated, FillRule::EvenOdd);
    obs.emit("accumulated", &accumulated);
    obs.emit("allUnion", &all_union);

    // 5-8. Pairwise layer interactions.
    let mut processed: Paths64 = Vec::new();
    for i in 0..geometry_layers.len() {
        let layer_union = union_self(&geometry_layers[i], FillRule::EvenOdd);
        obs.emit("layerUnion", &layer_union);
        for j in i + 1..geometry_layers.len() {
            let other_union = union_self(&geometry_layers[j], FillRule::EvenOdd);
            obs.emit("otherUnion", &other_union);

            let isect = intersect(&layer_union, &other_union, FillRule::EvenOdd);
            obs.emit("intersect", &isect);
            let diff = difference(&layer_union, &other_union, FillRule::EvenOdd);
            obs.emit("diff", &diff);
            let xorbit = xor(&layer_union, &other_union, FillRule::EvenOdd);
            obs.emit("xorbit", &xorbit);

            processed.extend(isect);
            processed.extend(diff);
            processed.extend(xorbit);
        }
    }

    // 9. Union of the processed results.
    let all_processed = union_self(&processed, FillRule::NonZero);
    obs.emit("processed", &processed);
    obs.emit("allProcessed", &all_processed);

    // 10-13. Offset sequence.
    let mut offset_results: Paths64 = Vec::new();
    let offsets = [2.0f64, -1.5, 3.0, -2.0];
    let join_types = [JoinType::Round, JoinType::Miter, JoinType::Square, JoinType::Bevel];
    for i in 0..4 {
        let offset = inflate_paths(&all_processed, offsets[i], join_types[i], EndType::Polygon, 2.0, 0.0);
        obs.emit("offsetStep", &offset);
        offset_results.extend(offset);
    }

    // 14. Union of the offsets.
    let union_offsets = union_self(&offset_results, FillRule::EvenOdd);
    obs.emit("offsetResults", &offset_results);
    obs.emit("unionOffsets", &union_offsets);

    // 15. Interact with the original union.
    let final_intersect = intersect(&union_offsets, &all_union, FillRule::EvenOdd);
    obs.emit("finalIntersect", &final_intersect);
    let final_diff = difference(&union_offsets, &all_union, FillRule::EvenOdd);
    obs.emit("finalDiff", &final_diff);
    let final_xor = xor(&union_offsets, &all_union, FillRule::EvenOdd);
    obs.emit("finalXor", &final_xor);

    // 16. Merge every final result.
    let mut all_final: Paths64 = Vec::new();
    all_final.extend(final_intersect);
    all_final.extend(final_diff);
    all_final.extend(final_xor);

    // 17. Final union.
    let final_union = union_self(&all_final, FillRule::NonZero);
    obs.emit("allFinal", &all_final);
    obs.emit("finalUnion", &final_union);

    // 18. Normalise by translation.
    let bounds = get_bounds(&final_union);
    obs.emit_rect("bounds", &bounds);
    let normalized = translate_paths(&final_union, bounds.left.wrapping_neg(), bounds.top.wrapping_neg());
    obs.emit("normalized", &normalized);

    // 19. Final offset.
    let last_offset = inflate_paths(&normalized, 1.0, JoinType::Round, EndType::Polygon, 2.0, 0.0);
    obs.emit("lastOffset", &last_offset);

    // 20. Aggregate.
    let mut total_area = 0.0f64;
    let mut total_perimeter = 0.0f64;
    let mut total_vertices: i64 = 0;

    for path in &last_offset {
        let a = area(path);
        total_area += a;
        total_vertices += path.len() as i64;

        if path.len() > 1 {
            for i in 0..path.len() {
                let j = (i + 1) % path.len();
                let dx = (path[j].x - path[i].x) as f64;
                let dy = (path[j].y - path[i].y) as f64;
                total_perimeter += (dx * dx + dy * dy).sqrt();
            }
        }
    }

    total_area * 0.7 + total_perimeter * 0.2 + (total_vertices as f64) * 0.1
}

