// test20 -- Rust port of tests/test20.cpp (Clipper2 "ultimate integration" test).
//
// Twenty chained Clipper2 API operations over three layers of generated geometry, reported as a
// single "complexity score". Everything the test needs -- the clipping engine, the offsetting
// engine and the C++ stream number formatting -- is implemented from scratch in `src/clipper`
// using only the standard library.

#[path = "src/clipper/mod.rs"]
mod clipper;

use clipper::fmt::ostream_double;
use clipper::pipeline::{compute, stoi, NoObserver};

fn main() {
    let args: Vec<String> = std::env::args().collect();

    // int complexity = (argc > 1) ? std::min(std::stoi(argv[1]), 5) : 3;
    let complexity = if args.len() > 1 {
        match stoi(&args[1]) {
            Some(v) => v.min(5),
            None => {
                // std::stoi throws std::invalid_argument, which terminates the process.
                eprintln!("terminate called after throwing an instance of 'std::invalid_argument'");
                eprintln!("  what():  stoi");
                std::process::abort();
            }
        }
    } else {
        3
    };

    let complexity_score = compute(complexity, &mut NoObserver);

    println!("{}", ostream_double(complexity_score));
}

