#[path = "/output/src/clipper/mod.rs"]
mod clipper;
use clipper::core::*;
use clipper::pipeline::{build_geometry, compute, Observer};

struct Printer { filter: Option<String> }
impl Observer for Printer {
    fn emit(&mut self, label: &str, paths: &[Path64]) {
        if let Some(f) = &self.filter { if f != label { return; } }
        println!("== {}", label);
        println!("PATHS {}", paths.len());
        for p in paths {
            let mut s = format!("L {}", p.len());
            for pt in p { s.push_str(&format!(" {} {}", pt.x, pt.y)); }
