        }
    }
    fn emit_rect(&mut self, label: &str, r: &Rect64) {
        if let Some(f) = &self.filter { if f != label { return; } }
        println!("== {}", label);
        println!("RECT {} {} {} {}", r.left, r.top, r.right, r.bottom);
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mode = args.get(1).cloned().unwrap_or_else(|| "pipeline".into());
    let cpx: i32 = args.get(2).map(|s| s.parse().unwrap()).unwrap_or(1);
