#[path = "/output/src/clipper/mod.rs"]
mod clipper;

use clipper::core::*;
use clipper::engine::{difference, intersect, union_self, xor};
use clipper::offset::inflate_paths;

fn fill_of(i: i32) -> FillRule {
    match i {
        0 => FillRule::EvenOdd,
        1 => FillRule::NonZero,
        2 => FillRule::Positive,
        _ => FillRule::Negative,
    }
}
fn join_of(i: i32) -> JoinType {
    match i {
        0 => JoinType::Square,
        1 => JoinType::Bevel,
        2 => JoinType::Round,
        _ => JoinType::Miter,
    }
}
fn end_of(i: i32) -> EndType {
    match i {
        0 => EndType::Polygon,
        1 => EndType::Joined,
        2 => EndType::Butt,
        3 => EndType::Square,
        _ => EndType::Round,
    }
}

fn main() {
    let path = std::env::args().nth(1).expect("spec file");
    let text = std::fs::read_to_string(path).unwrap();

    let mut op = String::new();
    let (mut fill, mut join, mut end) = (0i32, 0i32, 0i32);
    let (mut delta, mut miter, mut arctol) = (0.0f64, 2.0f64, 0.0f64);
    let (mut dx, mut dy) = (0i64, 0i64);
    let mut subject: Paths64 = Vec::new();
    let mut clip: Paths64 = Vec::new();
    let mut in_clip = false;

    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut it = line.split_whitespace();
        let kw = it.next().unwrap();
        match kw {
            "OP" => op = it.next().unwrap().to_string(),
            "FILL" => fill = it.next().unwrap().parse().unwrap(),
            "DELTA" => delta = it.next().unwrap().parse().unwrap(),
            "JOIN" => join = it.next().unwrap().parse().unwrap(),
            "END" => end = it.next().unwrap().parse().unwrap(),
            "MITER" => miter = it.next().unwrap().parse().unwrap(),
            "ARCTOL" => arctol = it.next().unwrap().parse().unwrap(),
            "DX" => dx = it.next().unwrap().parse().unwrap(),
            "DY" => dy = it.next().unwrap().parse().unwrap(),
            "SUBJECT" => in_clip = false,
            "CLIP" => in_clip = true,
            "PATH" => {
                let nums: Vec<i64> = it.map(|t| t.parse().unwrap()).collect();
                let p: Path64 = nums.chunks(2).map(|c| Point64::new(c[0], c[1])).collect();
                if in_clip {
                    clip.push(p)
                } else {
                    subject.push(p)
                }
            }
            k => panic!("bad directive {k}"),
        }
    }

    match op.as_str() {
        "bounds" => {
            let r = get_bounds(&subject);
            println!("RECT {} {} {} {}", r.left, r.top, r.right, r.bottom);
            return;
        }
        "area" => {
            println!("AREA {:.17}", area(&subject[0]));
            return;
        }
        _ => {}
    }

    let res: Paths64 = match op.as_str() {
        "union1" => union_self(&subject, fill_of(fill)),
        "intersect" => intersect(&subject, &clip, fill_of(fill)),
        "difference" => difference(&subject, &clip, fill_of(fill)),
        "xor" => xor(&subject, &clip, fill_of(fill)),
        "inflate" => inflate_paths(&subject, delta, join_of(join), end_of(end), miter, arctol),
        "translate" => translate_paths(&subject, dx, dy),
        o => panic!("unknown op {o}"),
    };

    println!("PATHS {}", res.len());
    for p in &res {
        let mut s = format!("L {}", p.len());
        for pt in p {
            s.push_str(&format!(" {} {}", pt.x, pt.y));
        }
        println!("{}", s);
    }
}

