// Generates a deterministic corpus of small op specs for differential testing.
// usage: gencorpus <outdir> [count]
use std::fmt::Write as _;

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        // splitmix64
        self.0 = self.0.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }
    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
    fn range(&mut self, lo: i64, hi: i64) -> i64 {
        lo + (self.next() % ((hi - lo + 1) as u64)) as i64
    }
}

fn rect(r: &mut Rng, span: i64) -> Vec<(i64, i64)> {
    let x = r.range(-span, span);
    let y = r.range(-span, span);
    let w = r.range(1, span);
    let h = r.range(1, span);
    let mut v = vec![(x, y), (x + w, y), (x + w, y + h), (x, y + h)];
    if r.below(2) == 0 {
        v.reverse();
    }
    v
}

fn poly(r: &mut Rng, span: i64, n: usize) -> Vec<(i64, i64)> {
    // star-shaped polygon around a centre so most are simple, some self-intersecting
    let cx = r.range(-span, span) as f64;
    let cy = r.range(-span, span) as f64;
    let mut v = Vec::new();
    for i in 0..n {
        let ang = std::f64::consts::TAU * (i as f64) / (n as f64);
        let rad = r.range(2, span.max(3)) as f64;
        v.push((
            (cx + rad * ang.cos()).round() as i64,
            (cy + rad * ang.sin()).round() as i64,
        ));
    }
    if r.below(2) == 0 {
        v.reverse();
    }
    v
}

fn rand_path(r: &mut Rng, span: i64) -> Vec<(i64, i64)> {
    // fully random points: lots of self-intersection, collinearity and duplicates
    let n = r.below(6) + 3;
    (0..n).map(|_| (r.range(-span, span), r.range(-span, span))).collect()
}

fn grid_path(r: &mut Rng) -> Vec<(i64, i64)> {
    // small-coordinate paths maximise coincident vertices / collinear edges / touching
    let n = r.below(6) + 3;
    (0..n).map(|_| (r.range(0, 4), r.range(0, 4))).collect()
}

fn emit(paths: &[Vec<(i64, i64)>], out: &mut String) {
    for p in paths {
        write!(out, "PATH").unwrap();
        for (x, y) in p {
            write!(out, " {} {}", x, y).unwrap();
        }
        out.push('\n');
    }
}

fn main() {
    let dir = std::env::args().nth(1).unwrap();
    let count: usize = std::env::args().nth(2).map(|s| s.parse().unwrap()).unwrap_or(300);
    std::fs::create_dir_all(&dir).unwrap();
    let mut r = Rng(0x2024_0517_1234_5678);

    let ops = ["union1", "intersect", "difference", "xor", "inflate"];
    let mut n = 0usize;
    while n < count {
        let op = ops[(n as usize) % ops.len()];
        // cycle through generators & scales so every regime is covered
        let kind = r.below(5);
        let span = match r.below(4) {
            0 => 4,
            1 => 12,
            2 => 60,
            _ => 400,
        };
        let mk = |r: &mut Rng| -> Vec<(i64, i64)> {
            match kind {
                0 => rect(r, span),
                1 => poly(r, span, (r.below(8) + 3) as usize),
                2 => rand_path(r, span),
                3 => grid_path(r),
                _ => {
                    if r.below(2) == 0 {
                        rect(r, span)
                    } else {
                        poly(r, span, 5)
                    }
                }
            }
        };
        let nsubj = (r.below(3) + 1) as usize;
        let subj: Vec<Vec<(i64, i64)>> = (0..nsubj).map(|_| mk(&mut r)).collect();
        let nclip = (r.below(3) + 1) as usize;
        let clip: Vec<Vec<(i64, i64)>> = (0..nclip).map(|_| mk(&mut r)).collect();

        let mut s = String::new();
        writeln!(s, "OP {}", op).unwrap();
        writeln!(s, "FILL {}", r.below(4)).unwrap();
        if op == "inflate" {
            let deltas = [1.0, -1.0, 2.5, -2.5, 7.0, -7.0, 0.5, 13.0];
            writeln!(s, "DELTA {:?}", deltas[r.below(8) as usize]).unwrap();
            writeln!(s, "JOIN {}", r.below(4)).unwrap();
            writeln!(s, "END 0").unwrap();
            writeln!(s, "MITER 2.0").unwrap();
            writeln!(s, "ARCTOL 0.0").unwrap();
        }
        s.push_str("SUBJECT\n");
        emit(&subj, &mut s);
        if op != "union1" && op != "inflate" {
            s.push_str("CLIP\n");
            emit(&clip, &mut s);
        }
        std::fs::write(format!("{}/c{:04}_{}.txt", dir, n, op), s).unwrap();
        n += 1;
    }
    eprintln!("wrote {} specs to {}", count, dir);
}

