    (0..n).map(|_| (r.range(0, 4), r.range(0, 4))).collect()
}

fn emit(paths: &[Vec<(i64, i64)>], out: &mut String) {
    for p in paths {
        write!(out, "PATH").unwrap();
        for (x, y) in p {
            write!(out, " {} {}", x, y).unwrap();
        }
        out.push('\n');
    }
}

fn main() {
    let dir = std::env::args().nth(1).unwrap();
    let count: usize = std::env::args().nth(2).map(|s| s.parse().unwrap()).unwrap_or(300);
    std::fs::create_dir_all(&dir).unwrap();
    let mut r = Rng(0x2024_0517_1234_5678);

    let ops = ["union1", "intersect", "difference", "xor", "inflate"];
    let mut n = 0usize;
    while n < count {
        let op = ops[(n as usize) % ops.len()];
        // cycle through generators & scales so every regime is covered
        let kind = r.below(5);
        let span = match r.below(4) {
            0 => 4,
            1 => 12,
            2 => 60,
            _ => 400,
        };
        let mk = |r: &mut Rng| -> Vec<(i64, i64)> {
            match kind {
                0 => rect(r, span),
                1 => poly(r, span, (r.below(8) + 3) as usize),
                2 => rand_path(r, span),
                3 => grid_path(r),
                _ => {
                    if r.below(2) == 0 {
                        rect(r, span)
                    } else {
                        poly(r, span, 5)
                    }
                }
            }
        };
        let nsubj = (r.below(3) + 1) as usize;
        let subj: Vec<Vec<(i64, i64)>> = (0..nsubj).map(|_| mk(&mut r)).collect();
        let nclip = (r.below(3) + 1) as usize;
        let clip: Vec<Vec<(i64, i64)>> = (0..nclip).map(|_| mk(&mut r)).collect();

        let mut s = String::new();
        writeln!(s, "OP {}", op).unwrap();
        writeln!(s, "FILL {}", r.below(4)).unwrap();
        if op == "inflate" {
            let deltas = [1.0, -1.0, 2.5, -2.5, 7.0, -7.0, 0.5, 13.0];
            writeln!(s, "DELTA {:?}", deltas[r.below(8) as usize]).unwrap();
            writeln!(s, "JOIN {}", r.below(4)).unwrap();
            writeln!(s, "END 0").unwrap();
            writeln!(s, "MITER 2.0").unwrap();
            writeln!(s, "ARCTOL 0.0").unwrap();
        }
        s.push_str("SUBJECT\n");
        emit(&subj, &mut s);
        if op != "union1" && op != "inflate" {
            s.push_str("CLIP\n");
            emit(&clip, &mut s);
        }
        std::fs::write(format!("{}/c{:04}_{}.txt", dir, n, op), s).unwrap();
        n += 1;
    }
    eprintln!("wrote {} specs to {}", count, dir);
}
